import {calculate,defaults} from './model.js';
const $=s=>document.querySelector(s);
export const escapeHtml=x=>String(x).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export const gbp=n=>n===null||!Number.isFinite(n)?'N/A':new Intl.NumberFormat('en-GB',{style:'currency',currency:'GBP',maximumFractionDigits:0}).format(n);
const fmt=(n,type='money')=>n===null||!Number.isFinite(n)?'N/A':type==='percent'?(n*100).toFixed(1)+'%':type==='ratio'?n.toFixed(2)+'×':type==='months'?n.toFixed(1)+' months':gbp(n);
export const METRICS=[
 ['cashLeftInDeal','Cash left in deal','money','b','Equity cash injected − signed cash available at refinance. Positive = remaining; negative = extra released.'],
 ['monthlyCashFlow','Monthly pre-tax cash flow','money','c','(NOI − annual debt service − annual cash reserves) ÷ 12.'],
 ['profitOnCost','Development profit on cost','percent','a','(GDV − total development cost) ÷ total development cost. Paper value uplift, not realised profit.'],
 ['gdv','GDV','money','a','Selected end value: manual estimate or indicative full-occupancy annual rent × multiplier.'],
 ['ltv','Refinance LTV','percent','b','Target gross refinance loan as a share of the supported refinance valuation; actual-loan overrides and caps are shown separately.'],
 ['dscr','DSCR','ratio','c','NOI ÷ annual debt service. Below 1.00× means operations do not cover scheduled debt service. N/A if debt service is zero.'],
 ['totalProjectCost','Total development cost','money','a','Acquisition + development + bridge finance + holding costs + entered refinance transaction and closing cash costs.'],
 ['developmentUplift','Development value uplift','money','a','GDV − total development cost. An unrealised valuation uplift, not cash proceeds or realised sale profit.'],
 ['profitOnGDV','Development profit on GDV','percent','a','Development value uplift ÷ GDV.'],
 ['fundingRequirement','Estimated equity funding requirement','money','a','Non-finance costs + holding costs + finance paid during development − net bridge advances. Not a peak monthly cash forecast.'],
 ['developmentDuration','Development duration','months','a','Purchase to completion when dates are supplied; otherwise the modelled bridge duration is used as an explicit approximation.'],
 ['refinanceValuation','Refinance valuation','money','b','Separate refinance valuation if supplied; otherwise the selected GDV assumption. Not automatically lender-confirmed.'],
 ['grossRefinanceLoan','Gross refinance loan','money','b','Supported refinance valuation × target LTV, subject to any loan cap or explicit actual-loan override.'],
 ['netRefinanceFunds','Net refinance funds','money','b','Gross refinance loan − fees retained or paid from the advance.'],
 ['redemption','Bridge redemption balance','money','b','Drawn bridge principal + rolled unretained interest + rolled unretained fees. Retained and already-paid charges are excluded.'],
 ['cashReturnedToInvestor','Cash returned at refinance','money','b','Maximum of zero and net funds less bridge redemption, other debts redeemed and closing cash costs.'],
 ['additionalCashRequired','Additional cash required at refinance','money','b','If cash available at refinance is negative, its absolute amount must be injected to complete refinance.'],
 ['totalEquityCashInjected','Equity cash injected','money','b','Sum of entered equity cash contributions in actual-ledger mode; otherwise the explicitly labelled funding estimate or override.'],
 ['capitalRecycled','Capital recycled','percent','b','Signed cash available at refinance ÷ equity cash injected. More than 100% means extra cash extracted; below 0% means a refinance top-up is needed.'],
 ['equityAfterRefinance','Equity after refinance','money','b','Refinance valuation − outstanding refinance mortgage − other retained secured debt.'],
 ['grossAnnualRent','Gross annual rent','money','c','Full-occupancy contracted monthly rent × 12.'],
 ['effectiveAnnualRent','Effective annual rent','money','c','Gross annual rent × occupancy. Bad debt is not separately modelled.'],
 ['annualOperatingExpenses','Annual operating expenses','money','c','Annual fixed costs plus variable costs and management. Excludes finance, tax, principal repayments and separately entered reserves.'],
 ['noi','Net operating income (NOI)','money','c','Effective annual rent − annual operating expenses, before finance, tax and separately entered reserves.'],
 ['grossYield','Gross rental yield','percent','c','Gross annual rent ÷ GDV.'],
 ['netOperatingYield','Net operating yield','percent','c','NOI ÷ GDV.'],
 ['annualDebtService','Annual debt service','money','c','Annual mortgage payment including scheduled principal, plus other recurring debt service.'],
 ['annualCashFlow','Annual pre-tax cash flow','money','c','NOI − annual debt service − separately entered recurring reserves.'],
 ['cashOnCash','Cash-on-cash return','percent','c','Annual pre-tax cash flow ÷ positive cash left in deal. N/A if cash left is zero or negative.'],
 ['breakEvenOccupancy','Break-even occupancy','percent','c','(Fixed annual operating costs + annual debt service) ÷ (full gross annual rent − variable costs at full occupancy). Before separate reserves.'],
 ['monthsToAllOut','Months of income to all money out','months','c','Your agreed measure: (25% purchase deposit + stamp duty + architects + legal + valuation + project fee) ÷ monthly rental surplus. Does not deduct refinance cash.']
];
let current=null;
const metricValue=(r,k)=>k==='ltv'?r.input.ltv:k==='redemption'?r.bridgeDetail.redemption:r[k];
const card=m=>`<article class="metric-card" data-metric="${m[0]}"><div class="metric-top"><span>${m[1]}</span><button class="metric-help" data-details="${m[0]}" title="${escapeHtml(m[4])}" aria-label="Calculation details: ${m[1]}">?</button></div>${m[0]==='ltv'?'<label class="ltv-control"><input id="summaryLtv" data-path="refinanceLtv" aria-label="Refinance LTV" type="number" min="0" max="100" step="any" required><span>%</span></label>':'<strong class="metric-number"></strong>'}<small class="metric-note"></small></article>`;
export function renderMetrics(p,active,r){
 current={p,active,r};const root=$('#kpis');
 if(!root.dataset.ready){
  root.innerHTML=`<div class="metrics-context"><span>Selected scenario · GBP · before tax</span><span id="estimateStatus"></span></div><div class="headline-metrics">${METRICS.slice(0,6).map(card).join('')}</div>`+[['a','A. Development performance'],['b','B. Refinance & capital recycling'],['c','C. Rental investment performance']].map(([group,title])=>`<details class="metric-section"><summary>${title}<span>Explore metrics & calculations</span></summary><div class="metric-grid">${METRICS.slice(6).filter(m=>m[3]===group).map(card).join('')}</div></details>`).join('');
  root.dataset.ready='yes';
 }
 const optional=Object.entries(p.extras).filter(([k,v])=>v===null&&!k.endsWith('Date')&&!['refinanceValuation','actualLoan','maxLoan','paymentOverride','managementOverride'].includes(k)).length;
 $('#estimateStatus').textContent=`${r.input.equityMode==='actual'?'Entered equity ledger':'Estimated equity ledger'} · ${optional} optional inputs not entered`;
 for(const m of METRICS){const el=root.querySelector(`[data-metric="${m[0]}"]`),v=metricValue(r,m[0]);
  if(m[0]==='ltv'){if(document.activeElement!==$('#summaryLtv'))$('#summaryLtv').value=Number((r.input.ltv*100).toFixed(4));}
  else el.querySelector('.metric-number').textContent=fmt(v,m[2]);
  let note='Estimate · details available';
  if(m[0]==='cashLeftInDeal')note=v===null?'Enter an equity ledger and valuation to calculate':v<0?'Released above original cash contribution':v>0?'Your cash remains invested':'All contributed cash recovered';
  if(m[0]==='gdv')note=r.input.valuationMode==='multiplier'?'Indicative · rent × multiplier':'Manual valuation assumption';
  if(m[0]==='ltv')note=p.extras.actualLoan!==null?'Actual loan override is active':p.extras.maxLoan!==null?'Loan cap applied if lower':'Target · default 75%';
  if(m[0]==='ltv'&&Math.abs(r.input.ltv*100-p.refinanceLtv)>.0001)note=`Temporary scenario · saved baseline ${p.refinanceLtv}%`;
  if(m[0]==='dscr')note=v===null?'N/A · no debt service or missing loan':v<1?'Below 1.00× · debt service not covered':'At or above 1.00× · debt service covered';
  if(m[0]==='cashOnCash'&&v===null)note='N/A · requires positive cash left in deal';
  if(m[0]==='capitalRecycled')note=v===null?'N/A · positive equity injection required':v>1?'Over 100% · includes excess cash extracted':v<0?'Below zero · refinance needs more cash':'Share of equity returned at refinance';
  if(m[0]==='additionalCashRequired')note=v===null?'N/A · enter refinance valuation':v>0?'Top-up needed to complete refinance':'No refinance top-up in this model';
  if(m[0]==='monthsToAllOut')note=v===null?'N/A · monthly surplus must be positive':`${gbp(r.recoveryCash)} ÷ ${gbp(r.net)} monthly surplus`;
  if(m[0]==='monthlyCashFlow'||m[0]==='annualCashFlow')note=p.extras.reserves===null?'Before tax · cash reserves not entered':'Before tax · after entered cash reserves';
  if(m[0]==='breakEvenOccupancy')note=v===null?'N/A · positive full-occupancy rent margin required':v>1?'Above 100% · not achievable at current rent and costs':'Operating costs and debt service; before reserves';
  el.querySelector('.metric-note').textContent=note;
  const bad=(m[0]==='cashLeftInDeal'&&v>0)||(m[0]==='additionalCashRequired'&&v>0)||(m[0]==='dscr'&&v!==null&&v<1)||(['developmentUplift','monthlyCashFlow','annualCashFlow','noi'].includes(m[0])&&v!==null&&v<0);
  el.classList.toggle('metric-negative',bad);el.classList.toggle('metric-released',m[0]==='cashLeftInDeal'&&v!==null&&v<0);
 }
 const dialog=$('#metricDialog');if(!dialog.dataset.ready){dialog.dataset.ready='yes';root.addEventListener('click',e=>{const b=e.target.closest('[data-details]');if(b)showMetric(b.dataset.details);});$('#closeMetric').addEventListener('click',()=>dialog.close());}
}
function showMetric(key){
 const {r,p,active}=current,m=METRICS.find(m=>m[0]===key),b=r.bridgeDetail;
 $('#metricDialogTitle').textContent=m[1];$('#metricFormula').textContent=m[4];$('#metricResult').textContent=fmt(metricValue(r,key),m[2]);
 let rows=[];
 if(m[3]==='a')rows=[...Object.entries(r.input.costs),['Bridge interest',b.interest],['Bridge fees',b.fees],['Other holding costs',r.input.holding],['Refinance advance fees',r.input.advanceFees],['Refinance closing cash costs',r.input.closingCosts],['Total development cost',r.totalProjectCost],['Selected GDV',r.gdv],['Value uplift (not realised profit)',r.developmentUplift]];
 if(m[3]==='b')rows=[['Facility limit',b.facilityLimit],['Drawn principal',b.principal],['Interest retained from advance',b.retainedInterest],['Fees retained from advance',b.retainedFees],['Net bridge cash advanced',b.netAdvance],['Interest paid during development',b.paidInterest],['Fees paid during development',b.paidFees],['Rolled interest',b.rolledInterest],['Rolled fees',b.rolledFees],['Bridge redemption',b.redemption],['Estimated equity required',r.estimatedEquity],['Equity cash injected used',r.totalEquityCashInjected],...r.input.equityContributions.map((c,i)=>[`Entered equity ${i+1}, month ${c.month}`,c.amount]),['Gross refinance loan',r.grossRefinanceLoan],['Refinance fees deducted from advance',r.input.advanceFees],['Net refinance funds',r.netRefinanceFunds],['Other debts redeemed',r.input.otherDebt],['Closing cash costs',r.input.closingCosts],['Signed cash available at refinance',r.cashAvailableAtRefinance],['Cash returned (never negative)',r.cashReturnedToInvestor],['Additional cash required',r.additionalCashRequired],['Signed cash left in deal',r.cashLeftInDeal],['Equity after refinance',r.equityAfterRefinance]];
 if(m[3]==='c')rows=[['Gross annual rent',r.grossAnnualRent],['Effective rent after occupancy',r.effectiveAnnualRent],...Object.entries(r.input.fixedMonthlyExpenses).map(([k,v])=>[k+' (annual)',v*12]),['Management (annual)',r.management*12],['Other variable operating costs (annual)',r.effectiveAnnualRent*r.input.variableRate],['Operating expenses',r.annualOperatingExpenses],['NOI',r.noi],['Annual debt service',r.annualDebtService],['Recurring reserves (annual)',r.input.reserves*12],['Annual pre-tax cash flow',r.annualCashFlow],['Monthly pre-tax cash flow',r.net],['Income recovery basis (25% deposit + six-item costs)',r.recoveryCash]];
 $('#metricLines').innerHTML=rows.map(([label,v])=>`<tr><th scope="row">${escapeHtml(label)}</th><td>${v===null?'N/A':new Intl.NumberFormat('en-GB',{style:'currency',currency:'GBP'}).format(v)}</td></tr>`).join('');
 $('#metricAssumptions').textContent=`${r.input.equityMode==='actual'?'Equity uses the entered contribution ledger. Check it includes every cash payment through refinance.':'Equity is estimated from project costs and net funding; it is not a verified record of actual cash injections.'} Optional blank costs are not verified zeros; totals treat them as zero until entered. ${p.extras.paymentOverride!==null?'Mortgage payment is overridden and will not automatically change with LTV.':''} ${r.input.valuationMode==='multiplier'?'Rent-multiplier valuation is indicative, not lender-confirmed.':'Manual valuation is an assumption, not a confirmed lending offer.'} No planning, licensing or lender eligibility is inferred from room count.`;
 $('#metricDialog').showModal();
}
const get=(p,path)=>path.split('.').reduce((a,k)=>a[k],p);
export function inputField(p,path,label,{unit='£',hint='',optional=true,min=0,max='',type='number'}={}){
 const value=get(p,path),kind=type==='date'?'date':'number';
 return `<label class="field"><span>${label}</span><div class="input-wrap">${unit==='£'?'<b>£</b>':''}<input type="${type}" data-path="${path}" data-kind="${kind}" aria-label="${label}" value="${escapeHtml(value??'')}" ${type==='number'?`min="${min}" step="any" ${max!==''?`max="${max}"`:''}`:''} ${optional?'':'required'} class="${unit==='£'?'money':unit?'has-suffix':''}" placeholder="${optional?'Not entered':''}">${unit&&unit!=='£'?`<b class="suffix">${unit}</b>`:''}</div><small>${hint||(optional?'Blank = not entered; treated as zero for cost estimates.':'')}</small></label>`;
}
export function selectField(p,path,label,choices){return `<label class="field"><span>${label}</span><select data-path="${path}" data-kind="string" aria-label="${label}">${choices.map(([v,t])=>`<option value="${v}" ${get(p,path)===v?'selected':''}>${t}</option>`).join('')}</select></label>`;}
const toggle=(p,path,label)=>`<label class="check-field"><input type="checkbox" data-path="${path}" data-kind="boolean" ${get(p,path)?'checked':''}> ${label}</label>`;
const ledger=(p,path,label)=>`<label class="field"><span>${label}</span><textarea aria-label="${label}" data-ledger="${path}" rows="4" placeholder="0, 100000&#10;2, 50000">${get(p,path).map(c=>`${c.month}, ${c.amount}`).join('\n')}</textarea><small>One entry per line: month from purchase, amount in GBP.</small></label><button class="apply-ledger" data-apply-ledger="${path}">Apply ledger</button>`;
export function advancedInputs(p,tab){
 const f=(path,label,opts)=>inputField(p,path,label,opts),s=(path,label,choices)=>selectField(p,path,label,choices);
 if(tab==='property')return `<details class="input-details"><summary>Additional costs & timing</summary>${[['acquisitionOther','Other acquisition costs'],['planning','Planning / licensing'],['contingency','Contingency'],['developmentOther','Other development costs'],['monthlyHolding','Holding costs / month']].map(([k,t])=>f('extras.'+k,t)).join('')}${f('extras.purchaseDate','Purchase date',{type:'date',unit:'',hint:'Optional date assumption.'})}${f('extras.completionDate','Works completion date',{type:'date',unit:'',hint:'Optional date assumption.'})}${f('extras.refinanceDate','Refinance date',{type:'date',unit:'',hint:'Optional date assumption.'})}${s('extras.timingMode','Bridge timing basis',[['months','Entered term in months'],['dates','Purchase-to-refinance dates']])}<p class="small">Date interest uses actual days ÷ 365.25 × 12. The bridge term is an assumption, not a guaranteed completion date.</p></details>`;
 if(tab==='income')return `<details class="input-details"><summary>Valuation & refinance costs</summary>${s('extras.valuationMode','Valuation mode',[['multiplier','Indicative rent multiplier'],['manual','Manual valuation']])}${f('extras.refinanceValuation','Separate refinance valuation',{hint:'Blank = selected GDV. Not lender-confirmed.'})}${f('extras.actualLoan','Actual refinance principal override',{hint:'Blank = calculated loan. An override is held fixed when LTV changes.'})}${f('extras.maxLoan','Maximum lender loan',{hint:'Optional loan cap; affordability constraints are not otherwise inferred.'})}${f('extras.valuationHaircut','Lender valuation haircut',{unit:'%',max:100})}${[['refinanceLenderFee','Lender fees from advance'],['refinanceLegal','Refinance legal fees from advance'],['refinanceValuationFee','Refinance valuation fee from advance'],['refinanceRetainedFee','Other retained refinance fees'],['closingCashCosts','Cash costs at refinance'],['otherDebt','Other debt redeemed at refinance'],['otherSecuredDebt','Other secured debt retained']].map(([k,t])=>f('extras.'+k,t)).join('')}</details><details class="input-details"><summary>Mortgage repayment & reserves</summary>${s('extras.mortgageType','Mortgage payment type',[['interestOnly','Interest only'],['repayment','Capital repayment']])}${f('extras.amortisationYears','Amortisation term',{unit:'yr',optional:false,min:.1,max:100,hint:'Default 25 years; used for repayment mortgages.'})}${f('extras.paymentOverride','Monthly mortgage payment override',{hint:'If entered, payment stays fixed when LTV or rates change.'})}${f('extras.otherMonthlyDebt','Other monthly debt service')}${f('extras.reserves','Separate monthly cash reserve',{hint:'Deducted after NOI. Do not duplicate costs already included in operating expenses.'})}</details><details class="input-details"><summary>Additional operating expenses</summary><p class="small">Enter only costs not already included in Bills. These fields are monthly; management and other variable rates apply to collected rent.</p>${f('extras.managementOverride','Management monthly amount override',{hint:'Blank = management percentage. Use only when a fixed amount is intended.'})}${f('extras.variableOperatingRate','Other variable operating costs',{unit:'%',max:100})}${[['insurance','Insurance / month'],['maintenance','Maintenance / month'],['compliance','Compliance / month'],['broadband','Broadband / month'],['cleaning','Cleaning / month'],['councilTax','Council tax / month'],['otherOperating','Other operating costs / month']].map(([k,t])=>f('extras.'+k,t)).join('')}</details>`;
 return p.options.map((o,i)=>{const path='options.'+i+'.';return `<details class="input-details"><summary>${escapeHtml(o.name)} · funding detail</summary>${s(path+'bridgeMode','Drawdown basis '+o.name,[['full','Full drawn balance'],['average','Simplified average drawn'],['schedule','Entered drawdown schedule']])}${f(path+'principalOverride','Drawn principal override '+o.name,{hint:'Blank = facility limit. Must not exceed the facility.'})}${f(path+'averageDrawnPercent','Average drawn share '+o.name,{unit:'%',max:100,optional:false,hint:'Default 50%; applies only in average-drawn mode.'})}${ledger(p,path+'draws','Bridge drawdowns '+o.name)}${s(path+'interestFrequency','Interest rate frequency '+o.name,[['monthly','Monthly rate'],['annual','Annual nominal rate']])}${toggle(p,path+'compound','Compound monthly interest')}${toggle(p,path+'rolledInterest','Roll unpaid interest into redemption (default)')}${toggle(p,path+'rolledFees','Roll unpaid fees into redemption (default)')}${[['retainedInterest','Interest withheld from advance'],['retainedFees','Fees withheld from advance'],['arrangementFee','Additional arrangement fee'],['exitFee','Additional exit fee'],['brokerFee','Broker fee'],['monitoringFee','Monitoring fee'],['fundingLegalFee','Funding legal fee not already included'],['extensionFee','Extension fee']].map(([k,t])=>f(path+k,t+' '+o.name)).join('')}${s(path+'equityMode','Equity contribution basis '+o.name,[['estimated','Estimated from funding and costs'],['actual','Entered actual equity ledger']])}${f(path+'equityOverride','Estimated equity override '+o.name,{hint:'Optional estimate override; ignored when using the actual contribution ledger.'})}${ledger(p,path+'equityContributions','Actual equity contributions '+o.name)}<p class="small">Combined fee percentage is charged on drawn principal. Use zero there if you enter the same arrangement/exit fees as cash amounts. Retentions must not exceed their corresponding charges. Actual entries should include all equity paid through refinance, including fees, overruns and finance paid in cash. The ledger is not automatically uplifted in stress cases.</p></details>`;}).join('');
}
const stressChoices={valuation:{label:'Refinance valuation change (%)',values:[0,-5,-10,-15],key:'valuationChange'},ltv:{label:'Refinance LTV (%)',values:[65,70,75],key:'ltv'},build:{label:'Build overrun (%)',values:[0,10,20],key:'buildChange'},term:{label:'Bridge term (months)',values:[4,6,9],key:'bridgeTerm'},rent:{label:'Rent change (%)',values:[0,-5,-10],key:'rentChange'},occupancy:{label:'Occupancy change (%)',values:[0,-5,-10],key:'occupancyChange'},rate:{label:'Mortgage rate stress (+pp)',values:[0,1,2],key:'ratePoints'}};
export function setupSensitivity(onApply,onChange){
 const root=$('#extendedSensitivity');root.innerHTML=`<div class="section-title"><div><h2>Key metric sensitivity</h2><p>One assumption changes per row; saved baseline inputs stay unchanged.</p></div></div><div class="sensitivity-controls"><label>Assumption<select id="sensitivityDimension">${Object.entries(stressChoices).map(([k,c])=>`<option value="${k}">${c.label}</option>`).join('')}</select></label><label>Values (comma separated)<input id="sensitivityValues" aria-label="Sensitivity values"></label><button id="applySensitivityValues">Update table</button></div><p id="stressContext" class="small"></p><div id="sensitivityTable" class="table-scroll"></div>`;
 $('#sensitivityDimension').addEventListener('change',()=>{root.dataset.values='';onChange();});
 $('#applySensitivityValues').addEventListener('click',()=>{const vals=$('#sensitivityValues').value.split(',').map(v=>Number(v.trim()));if(vals.length>12||!vals.length||vals.some(v=>!Number.isFinite(v)))return onChange('Enter up to 12 finite, comma-separated values.');root.dataset.values=JSON.stringify(vals);onChange();});
 root.addEventListener('click',e=>{const b=e.target.closest('[data-sensitivity-value]');if(!b)return;const c=stressChoices[$('#sensitivityDimension').value];onApply(c.key,Number(b.dataset.sensitivityValue));});
}
export function renderSensitivity(p,active){const c=stressChoices[$('#sensitivityDimension').value],root=$('#extendedSensitivity'),values=root.dataset.values?JSON.parse(root.dataset.values):c.values;$('#sensitivityValues').value=values.join(', ');
 $('#stressContext').textContent=`Baseline ${p.options[active].name}; other cost amounts, rates and occupancy held constant. Funding percentages are held, so build facilities scale with build budget. ${p.extras.valuationMode==='manual'?'Manual GDV stays fixed when rent changes.':'Indicative multiplier GDV changes with room rent.'} Actual equity ledgers and loan/payment overrides stay fixed. Date timing is replaced by a term stress.`;
 $('#sensitivityTable').innerHTML=`<table class="stress-table"><thead><tr><th>${c.label}</th><th>Cash left in deal</th><th>Additional cash</th><th>Monthly cash flow</th><th>DSCR</th><th>Equity</th></tr></thead><tbody>${values.map(v=>{try{if((c.key==='ltv'&&(v<0||v>100))||(['valuationChange','rentChange','occupancyChange'].includes(c.key)&&(v< -100||v>100))||(['bridgeTerm','buildChange','ratePoints'].includes(c.key)&&v<0))throw Error('Value outside the supported range.');const r=calculate(p,active,c.key==='rentChange'?v:0,0,c.key==='rentChange'?{}:{[c.key]:v});return `<tr><th><button data-sensitivity-value="${v}" title="Apply this temporary scenario">${v} · apply</button></th><td>${fmt(r.left)}<small>${r.left===null?'Missing equity / valuation':r.left<0?'released':'remaining'}</small></td><td>${fmt(r.additionalCashRequired)}</td><td>${fmt(r.net)}</td><td>${fmt(r.dscr,'ratio')}</td><td>${fmt(r.equity)}</td></tr>`;}catch(err){return `<tr><th>${v}</th><td colspan="5">${escapeHtml(err.message)}</td></tr>`;}}).join('')}</tbody></table>`;
}
export function comparison(p,rentChange,delay,stress){
 const basis=$('#comparisonBasis').value,sort=$('#comparisonSort').value,source=structuredClone(p);
 const differing=p.options[0].legal!==p.options[1].legal||p.options[0].valuation!==p.options[1].valuation;
 if(basis==='normalised'){source.options[1].legal=source.options[0].legal;source.options[1].valuation=source.options[0].valuation;}
 $('#comparisonWarning').textContent=basis==='normalised'?'Legal and acquisition valuation costs normalised to Option A for this comparison only. Financing and entered actual-equity ledgers stay independent.':differing?`Not like-for-like: acquisition legal and valuation costs differ by ${gbp((p.options[0].legal+p.options[0].valuation)-(p.options[1].legal+p.options[1].valuation))}. Choose normalised costs for a financing-only cost comparison.`:'Non-finance cost assumptions match.';
 const results=[0,1].map(i=>({name:p.options[i].name,r:calculate(source,i,rentChange,delay,stress)})).sort((a,b)=>{const av=a.r[sort],bv=b.r[sort];if(av===null)return 1;if(bv===null)return -1;return sort==='left'?av-bv:bv-av;});
 const rows=[['Base project cost','cost'],['Drawn bridge principal','borrowed'],['Bridge finance cost','bridge'],['Bridge redemption balance','redemption'],['Total development cost','allIn'],['GDV','value'],['Development value uplift','developmentUplift'],['Profit on cost','profitOnCost'],['Net refinance funds','netRefinanceFunds'],['Equity cash injected','initial'],['Cash returned to investor','cashReturned'],['Additional refinance cash required','additionalCashRequired'],['Signed cash left in deal','left'],['Capital recycled','capitalRecycled'],['Equity after refinance','equity'],['NOI (annual)','noi'],['Monthly pre-tax cash flow','net'],['DSCR','dscr'],['Initial cash for income recovery','recoveryCash'],['Months of income to all money out','monthsToAllOut']];
 $('#comparison').innerHTML=`<table class="compare-table"><thead><tr><th>Appraisal measure</th>${results.map(x=>`<th>${escapeHtml(x.name)}</th>`).join('')}</tr></thead><tbody>${rows.map(([label,k])=>`<tr><th scope="row">${label}</th>${results.map(({r})=>`<td>${fmt(k==='redemption'?r.bridgeDetail.redemption:r[k],['profitOnCost','capitalRecycled'].includes(k)?'percent':k==='dscr'?'ratio':k==='monthsToAllOut'?'months':'money')}</td>`).join('')}</tr>`).join('')}</tbody></table>`;
}
